import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const PATH_DISCLAIMER =
  'Educational pathology mechanisms only. Normal 3D reference meshes are used purely for spatial orientation and do not depict patient-specific lesions or diagnostic pathology.';

const PATH_ASSET_GAP = {
  status: 'asset_required' as const,
  summary:
    'General and organ-system pathology mechanisms, morphological criteria, and 3D anatomical mechanism explainers (Coronary Ischaemia, Pituitary–Optic Chiasm, Hepatic Portal Venous Congestion) on normal reference meshes are implemented. Genuine licensed gross pathology specimens and histopathology slides are NOT bundled locally (use external Edinburgh Pathologia & Utah WebPath portals; zero synthetic specimens substituted).',
  missingAssets: ['Licensed CC-BY/educational histopathology H&E micrographs and gross pathology reference specimens'],
};

function makePathChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  morphologyNote: string,
  extraReadKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'pathology',
    chapterCode: `J${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['medical_foundations', 'clinical_applied', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 3–4', unitOrModule: `General & Systemic Pathology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Professional II–III', unitOrModule: `Pathology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Pathophysiology Block', unitOrModule: `Disease Mechanisms (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Cellular & Translational Pathology (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Normal histology microanatomy (Domain C)', 'Normal homeostatic physiology (Domain E)'],
    learningObjectives: [
      `Explain the aetiology, molecular pathogenesis, and sequential morphologic stages of ${chapterTitle.toLowerCase()}.`,
      `Distinguish reversible versus irreversible structural hallmarks expected microscopically (${morphologyNote}).`,
      `Correlate organ pathology in ${chapterTitle.toLowerCase()} with clinical signs, serum biomarkers, and normal 3D anatomical landmarks.`,
    ],
    depthExplanations: {
      medical_foundations: `${mechanisms.join(' ')} Expected gross & microscopic findings: ${morphologyNote}. Note: inspect external Pathologia/WebPath micrographs because local licensed histopathology slides remain Asset Required.`,
      clinical_applied: `Clinical correlation in ${chapterTitle.toLowerCase()} translates tissue pathology into bedside biomarkers, radiological shadows, and natural history: ${clinical}`,
      graduate_research: `Molecular pathology dissects driver mutations, epigenetic plasticity, cytokine/inflammasome signalling, and spatial tissue transcriptomics governing ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Pathogenetic Mechanism', definition: summary },
      { term: 'Morphological Signature', definition: morphologyNote },
      { term: 'Clinical & Laboratory Expression', definition: clinical },
    ],
    keyFacts: [
      `Expected pathology features: ${morphologyNote}.`,
      '3D Anatomy Explorer & Presentation Studio demonstrate organ spatial relations on normal BodyParts3D reference meshes only.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Necrosis and apoptosis produce the same tissue inflammation.', correction: 'Necrosis ruptures plasma membranes releasing DAMPs that trigger intense neutrophilic inflammation; apoptosis packages apoptotic bodies cleanly for macrophage efferocytosis with zero acute inflammation.' },
      { misconception: 'All benign tumours are completely harmless and all malignant tumours grow identically.', correction: 'Anatomically critical benign tumours (e.g., meningioma, pituitary macroadenoma pressing the optic chiasm) cause severe morbidity by mass effect despite lacking metastatic spread.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} traces how molecular insults remodel cells, extracellular matrix, and organ function. Local histopathology photos remain explicitly marked Asset Required alongside verified Pathologia and WebPath links.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      morphologyNote,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'histology', relation: 'Pathologic atypia, necrosis, and fibrosis can only be recognized against normal microanatomy.' },
      { domainId: 'pharmacology', relation: 'Therapeutics target specific inflammatory, coagulative, or oncogenic drivers defined by pathology.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['clinical_case', '2d_diagram', '3d_anatomy', 'microscopy'],
    diagram: {
      id: `diag-j${num}`,
      title: `${chapterTitle} — Aetiology → Pathogenesis → Morphology Sequence`,
      kind: 'pathway',
      caption: `${summary} (${morphologyNote})`,
      disclaimer: PATH_DISCLAIMER,
      nodes: [
        { id: 'n1', label: 'Aetiologic Trigger', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Tissue Morphologic Shift', sublabel: morphologyNote.slice(0, 62), tone: 'rose' },
        { id: 'n3', label: 'Organ Dysfunction', sublabel: clinical.slice(0, 62), tone: 'slate' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Biochemical injury & host reaction' },
        { from: 'n2', to: 'n3', label: 'Clinical biomarkers & functional failure' },
      ],
    },
    assetDisclosure: PATH_ASSET_GAP,
    activity: {
      title: `Pathogenetic & Morphologic Correlation (${chapterTitle})`,
      kind: 'case_reasoning',
      prompt: `Review the external Edinburgh Pathologia or Utah WebPath virtual specimens for ${chapterTitle}, link them to ${fmas.length > 0 ? '3D reference organs' : 'normal histology baselines'}, and justify the expected laboratory findings.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['edinburgh_pathologia', 'utah_webpath', extraReadKey],
    shortAnswers: [
      { id: `sa-j${num}-1`, prompt: `Trace the primary biochemical/cellular pathogenesis of ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-j${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} histologically and clinically.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'medical_foundations' },
      { id: `sa-j${num}-3`, prompt: `Explain how organ pathology in ${chapterTitle.toLowerCase()} produces the clinical presentation and lab signature.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-j${num}-1`,
      title: `Clinicopathological Correlation (CPC) Exercise: ${chapterTitle}`,
      scenario: `A teaching pathology specimen demonstrates ${morphologyNote.toLowerCase()} arising from ${summary.toLowerCase()}.`,
      questions: ['Which upstream cellular lesion initiated this morphology?', 'What downstream systemic complication threatens the patient?'],
      workedSolution: `${mechanisms[0]} Morphologic signature: ${morphologyNote}. Clinical consequence: ${clinical}`,
      level: 'clinical_applied',
      disclaimer: PATH_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: PATH_DISCLAIMER,
  };
}

